function serializarPublico(objeto) {
  return JSON.stringify(objeto, (chave, valor) => {
    if (chave.startsWith("_")) return undefined;
    if (chave === "palavraPasse") return "***";
    return valor;
  });
}

const utilizador = {
  nome: "Ana",
  palavraPasse: "segredo123",
  _token: "abc",
  perfil: { pais: "Portugal", _interno: 1 }
};

console.log(serializarPublico(utilizador));
// {"nome":"Ana","palavraPasse":"***","perfil":{"pais":"Portugal"}}

function lerJSONSeguro(texto, alternativa) {
  try {
    return { ok: true, valor: JSON.parse(texto) };
  } catch (erro) {
    if (!(erro instanceof SyntaxError)) throw erro;
    return { ok: false, valor: alternativa };
  }
}

const armazenamento = {
  definicoes: '{"tema":"escuro","tamanho":14}',
  rascunho: "{tema:'escuro'}",
  vazio: ""
};

for (const [chave, texto] of Object.entries(armazenamento)) {
  const resultado = lerJSONSeguro(texto, {});
  console.log(chave, resultado.ok, JSON.stringify(resultado.valor));
}
// definicoes true {"tema":"escuro","tamanho":14}
// rascunho false {}
// vazio false {}

class Tarefa {
  constructor(titulo, prazo, concluida = false) {
    this.titulo = titulo;
    this.prazo = prazo;
    this.concluida = concluida;
  }

  estaAtrasada(agora) {
    return !this.concluida && this.prazo.getTime() < agora.getTime();
  }

  toJSON() {
    return {
      __tipo: "Tarefa",
      titulo: this.titulo,
      prazo: this.prazo.toISOString(),
      concluida: this.concluida
    };
  }

  static reviver(chave, valor) {
    if (valor !== null && typeof valor === "object" && valor.__tipo === "Tarefa") {
      return new Tarefa(valor.titulo, new Date(valor.prazo), valor.concluida);
    }
    return valor;
  }
}

const tarefas = [
  new Tarefa("Escrever relatorio", new Date("2026-03-15T10:00:00Z")),
  new Tarefa("Rever codigo", new Date("2026-04-01T09:00:00Z"), true)
];

const texto = JSON.stringify(tarefas);
console.log(texto.includes('"__tipo":"Tarefa"')); // true

const lidas = JSON.parse(texto, Tarefa.reviver);
console.log(lidas[0] instanceof Tarefa);     // true
console.log(lidas[0].prazo instanceof Date); // true

const agora = new Date("2026-03-20T00:00:00Z");
console.log(lidas[0].estaAtrasada(agora)); // true
console.log(lidas[1].estaAtrasada(agora)); // false
